import { CUE_FILE_FOLDER, CUE_IDS, type CueId } from './sound-cues'

// Which file each cue ships and where it is from (#536): the shape of `credits.json` beside the cue files, written by
// `scripts/ship-cue-sound.mjs` and read by the file test and the listening page. Every sound is CC0 or generated by us, so nothing needs a
// credit in the app; the file is the record. A util, not test code: the listening page parses it too, and the test needs real red cases.

/** Where the credits file is served from, beside the cue files. */
export const CUE_CREDITS_URL = `${CUE_FILE_FOLDER}/credits.json`

export type Licence = 'CC0' | 'generated'

export interface CueCredit {
  /** The `name` of the candidate in `sound-candidates/manifest.json` the shipped file is a byte copy of. */
  candidate: string
  /** A URL or how it was made, as the manifest says. */
  source: string
  author: string | null
  licence: Licence
}

const KEYS = ['candidate', 'source', 'author', 'licence']
const isText = (value: unknown): value is string => typeof value === 'string' && value.trim() !== ''
const isObject = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value)

/** What is wrong with one entry, in German, or null. */
function faultOf(entry: unknown): string | null {
  if (!isObject(entry)) return 'ist kein Objekt'
  if (!isText(entry.candidate)) return '"candidate" fehlt oder ist leer'
  if (!isText(entry.source)) return '"source" fehlt oder ist leer'
  if (entry.author !== null && !isText(entry.author)) return '"author" ist weder ein Name noch null'
  if (entry.licence !== 'CC0' && entry.licence !== 'generated') return `Lizenz "${String(entry.licence)}" ist nicht CC0 oder generated`
  const extra = Object.keys(entry).find(key => !KEYS.includes(key))
  return extra === undefined ? null : `der Schlüssel "${extra}" ist nicht vorgesehen`
}

/**
 * The credits of every cue that has a valid entry, and a German problem line for everything else (a cue with no entry, an unknown cue id, a
 * faulty entry, which is left out). Never throws: the listening page shows the problems in red, the file test asserts there are none.
 */
export function parseCredits(raw: unknown): { credits: Partial<Record<CueId, CueCredit>>, problems: string[] } {
  const credits: Partial<Record<CueId, CueCredit>> = {}
  const problems: string[] = []
  const cues = isObject(raw) ? raw.cues : undefined
  if (!isObject(cues)) {
    problems.push('credits.json: "cues" fehlt oder ist kein Objekt.')
    return { credits, problems }
  }

  for (const key of Object.keys(cues)) {
    if (!CUE_IDS.some(id => id === key)) problems.push(`${key}: keine Cue-ID.`)
  }
  for (const id of CUE_IDS) {
    const entry = cues[id]
    if (entry === undefined) {
      problems.push(`${id}: kein Eintrag.`)
      continue
    }
    const fault = faultOf(entry)
    if (fault) problems.push(`${id}: ${fault}.`)
    else credits[id] = entry as CueCredit
  }
  return { credits, problems }
}
